-- Помилки програм людською мовою
INSERT INTO changelog (title, body, created_at) VALUES ('Помилки програм — простими словами', 'Проєкти → програма → «Звʼязок»: замість журналу подій тепер «Стан програми · 7 днів» — кожна проблема одним блоком: що сталось, чим загрожує, що зробити і кому (жовтим — те, що маєш зробити ти; «мине само» — нічого не робити). Однакові помилки склеєні з лічильником. Незнайомі — кнопка «Пояснити простими словами» (Джері пояснює один раз і запамʼятовує). Сирий журнал — згорнутий «Технічний журнал (для Claude)». У «Що виправити» помилки теж підписані простими словами.', datetime('now'));
